update sc_plans set spec=jsonb_set(spec,'{shots}',coalesce(spec->'shots','[]'::jsonb) || $q$[{"n": 1, "id": "gh1_spoon", "vid": "ghv1_spoon", "img_prompt": "GRANDMA (years ago): a Korean grandma in her late sixties, black-grey hair in a low bun, round kind face, indigo quilted vest over a cream blouse. GIRL (years ago): her granddaughter about five, round face, short black bob with bangs, bright red knit cardigan. PLACE: a hanok courtyard with a wooden porch (maru), a jangdokdae of round brown earthenware crocks on a stone platform, a wooden gate with a small tiled roof, a persimmon tree. Years ago, golden autumn on the wooden porch. The grandma feeds the little girl a spoonful of soft, glossy red ripe persimmon (hongsi) with a small brass spoon with a tiny heart engraved on the handle; the girl opens her mouth wide, eyes squeezed shut in joy. A bowl holding one soft red persimmon sits between them. Hands mostly hidden by the bowl. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": [], "reuse": null, "action": "The girl takes the spoonful and her cheeks puff up in a happy smile; the grandma laughs softly.", "dur": 5, "cap": "She always saved the ripest one for me.", "detail": "하트 새긴 놋숟가락"}, {"n": 2, "id": "gh2_wait", "vid": "ghv2_wait", "img_prompt": "GRANDMA (now): the same Korean grandma, now in her eighties, snow-white hair in a low bun, deeper smile wrinkles, the same indigo quilted vest, a little more bent. a small brass spoon with a tiny heart engraved on the handle PLACE: a hanok courtyard with a wooden porch (maru), a jangdokdae of round brown earthenware crocks on a stone platform, a wooden gate with a small tiled roof, a persimmon tree. Now, a snowy winter afternoon. The grandma, alone, stands beside the snowy jangdokdae with her hands tucked into her sleeves; on the closed lid of one earthenware crock, one perfect glossy red persimmon rests on a small white dish beside the brass spoon. She looks toward the closed wooden gate with quiet longing. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/gh1_spoon.jpeg"], "reuse": null, "action": "The grandma slowly turns her head toward the gate; snowflakes fall softly onto the crocks.", "dur": 5, "cap": "Every winter, she kept one. Just in case.", "detail": "장독 위 홍시 하나 + 놋숟가락"}]$q$::jsonb) where id='P261031-grandma-hongsi'